function decodeBase64Url(data) {
  if (!data) return '';

  let base64 = data
    .replace(/-/g, '+')
    .replace(/_/g, '/');

  while (base64.length % 4) {
    base64 += '=';
  }

  return Buffer.from(base64, 'base64').toString('utf8');
}

function extractPlainText(payload) {
  const texts = [];

  function walk(part) {
    if (!part) return;

    if (part.mimeType === 'text/plain' && part.body?.data) {
      texts.push(decodeBase64Url(part.body.data));
    }

    if (Array.isArray(part.parts)) {
      for (const child of part.parts) {
        walk(child);
      }
    }
  }

  walk(payload);
  return texts.join('\n');
}

const thread = $json;
const messages = thread.messages || [];

if (messages.length === 0) {
  return [{
    json: {
      threadId: thread.id || '',
      thread_text: ''
    }
  }];
}

// El último mensaje suele contener también la cadena anterior
const latestMessage = messages[messages.length - 1];

let text = extractPlainText(latestMessage.payload);

// ----------------------------------------------------
// LIMPIEZA DE CONTENIDO NO OPERATIVO
// ----------------------------------------------------

text = text
  // Normalizar saltos de línea
  .replace(/\r/g, '')

  // Eliminar URLs entre corchetes
  .replace(/\[https?:\/\/[^\]]+\]/gi, '')

  // Eliminar URLs sueltas
  .replace(/https?:\/\/\S+/gi, '')

  // Eliminar líneas que contienen solamente sitios web
  .replace(/^www\..*$/gim, '')

  // Eliminar datos típicos de firma corporativa
  .replace(/^Jefe de Registro de Datos.*$/gim, '')
  .replace(/^Autopista Tte\..*$/gim, '')
  .replace(/^T:\s*\+?\d+.*$/gim, '')

  // Eliminar textos de logos
  .replace(/^\[Logo.*\]$/gim, '')

  // Eliminar disclaimer del CRM
  .replace(
    /Por favor,\s*asegúrese de que su respuesta sea completa[\s\S]*?Gracias\./gi,
    ''
  )

  // Compactar espacios
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// ----------------------------------------------------
// EXTRAER NÚMERO DE CASO PARA AYUDAR AL AGENTE
// ----------------------------------------------------

const caseMatches = [
  ...text.matchAll(/(?:Subcaso|Caso)\s*#?\s*(\d{6,10})/gi)
];

const numeroCaso =
  caseMatches.length > 0
    ? caseMatches[caseMatches.length - 1][1]
    : '';

// ----------------------------------------------------
// RESULTADO
// ----------------------------------------------------

return [{
  json: {
    threadId: thread.id || '',
    numero_caso_detectado: numeroCaso,
    thread_text: text
  }
}];

